/*
  File: 01_seed_outer_tables_realistic_no_fk.sql
  Project: Nhóm 2 - TechTonic Ecommerce
  Purpose:
  - Seed dữ liệu mô phỏng nhìn giống người dùng/cửa hàng thật cho các bảng KHÔNG CÓ FOREIGN KEY đi tới bảng khác.
  - Chạy sau file tạo schema: SQLServer_Nhom2.sql.
  - Đây KHÔNG phải dữ liệu cá nhân thật. Email dùng domain .local và các tên/số điện thoại là dữ liệu synthetic phục vụ phát triển, Postman Mock API và demo.

  Bảng được seed trong bước này:
  1. roles: 4 role hệ thống đã chốt
  2. permissions: 38 quyền lõi theo chức năng tối thiểu
  3. users: 1.000 người dùng demo có tên Việt Nam, email/phone/ảnh đại diện mô phỏng
  4. stores: 1.000 cửa hàng demo có tên shop, địa chỉ, hotline, mô tả mô phỏng

  Gợi ý chạy:
  - Tốt nhất chạy trên database vừa reset bằng SQLServer_Nhom2.sql.
  - Nếu đã seed file cũ, nên reset schema rồi chạy file này để tránh trộn dữ liệu demo cũ/mới.
*/

USE TechTonicEcommerce_Nhom2;
GO

SET NOCOUNT ON;
GO

/* =========================================================
   1) roles - dữ liệu hệ thống, không tạo 1.000 role giả
   ========================================================= */
MERGE roles AS target
USING (VALUES
    ('CUSTOMER', N'Người mua', N'Người dùng mua hàng, quản lý tài khoản cá nhân, đơn hàng, đánh giá và nhắn tin cửa hàng.', 1, 'ACTIVE'),
    ('SELLER', N'Người bán', N'Người dùng quản lý cửa hàng, sản phẩm, đơn hàng và doanh thu cửa hàng mình.', 1, 'ACTIVE'),
    ('ADMIN', N'Admin', N'Quản trị nghiệp vụ toàn hệ thống.', 1, 'ACTIVE'),
    ('SHIPPER', N'Vận chuyển', N'Role phụ xử lý giao nhận đơn được phân công.', 1, 'ACTIVE')
) AS source (role_code, role_name, description, is_system_role, status)
ON target.role_code = source.role_code
WHEN MATCHED THEN
    UPDATE SET
        role_name = source.role_name,
        description = source.description,
        is_system_role = source.is_system_role,
        status = source.status,
        updated_at = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (role_code, role_name, description, is_system_role, status)
    VALUES (source.role_code, source.role_name, source.description, source.is_system_role, source.status);
GO

