/* =========================================================
   3) users - 1.000 người dùng demo nhìn giống dữ liệu thật
   ========================================================= */
DECLARE @SeedUsers TABLE (
    email NVARCHAR(255) NOT NULL,
    phone VARCHAR(20) NOT NULL,
    password_hash NVARCHAR(255) NOT NULL,
    full_name NVARCHAR(150) NOT NULL,
    avatar_url NVARCHAR(500) NULL,
    gender VARCHAR(10) NULL,
    birth_date DATE NULL,
    status VARCHAR(20) NOT NULL,
    last_login_at DATETIME2(0) NULL,
    created_at DATETIME2(0) NOT NULL
);


MERGE users AS target
USING @SeedUsers AS source
ON target.email = source.email
WHEN MATCHED THEN
    UPDATE SET
        phone = source.phone,
        password_hash = source.password_hash,
        full_name = source.full_name,
        avatar_url = source.avatar_url,
        gender = source.gender,
        birth_date = source.birth_date,
        status = source.status,
        last_login_at = source.last_login_at,
        updated_at = SYSUTCDATETIME(),
        deleted_at = NULL
WHEN NOT MATCHED THEN
    INSERT (email, phone, password_hash, full_name, avatar_url, gender, birth_date, status, last_login_at, created_at, updated_at)
    VALUES (source.email, source.phone, source.password_hash, source.full_name, source.avatar_url, source.gender, source.birth_date, source.status, source.last_login_at, source.created_at, SYSUTCDATETIME());
GO

/* =========================================================
   4) stores - 1.000 cửa hàng demo nhìn giống shop thật
   ========================================================= */
DECLARE @SeedStores TABLE (
    store_code VARCHAR(30) NOT NULL,
    store_name NVARCHAR(150) NOT NULL,
    slug NVARCHAR(191) NOT NULL,
    description NVARCHAR(MAX) NULL,
    logo_url NVARCHAR(500) NULL,
    contact_email NVARCHAR(255) NULL,
    contact_phone VARCHAR(20) NULL,
    address_line NVARCHAR(255) NULL,
    ward NVARCHAR(100) NULL,
    district NVARCHAR(100) NULL,
    province NVARCHAR(100) NULL,
    total_products INT NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at DATETIME2(0) NOT NULL
);


MERGE stores AS target
USING @SeedStores AS source
ON target.store_code = source.store_code
WHEN MATCHED THEN
    UPDATE SET
        store_name = source.store_name,
        slug = source.slug,
        description = source.description,
        logo_url = source.logo_url,
        contact_email = source.contact_email,
        contact_phone = source.contact_phone,
        address_line = source.address_line,
        ward = source.ward,
        district = source.district,
        province = source.province,
        total_products = source.total_products,
        status = source.status,
        updated_at = SYSUTCDATETIME(),
        deleted_at = NULL
WHEN NOT MATCHED THEN
    INSERT (store_code, store_name, slug, description, logo_url, contact_email, contact_phone, address_line, ward, district, province, total_products, status, created_at, updated_at)
    VALUES (source.store_code, source.store_name, source.slug, source.description, source.logo_url, source.contact_email, source.contact_phone, source.address_line, source.ward, source.district, source.province, source.total_products, source.status, source.created_at, SYSUTCDATETIME());
GO

/* =========================================================
   5) Kiểm tra nhanh sau khi seed
   ========================================================= */
SELECT 'users' AS table_name, COUNT(*) AS total_rows FROM users
UNION ALL
SELECT 'roles', COUNT(*) FROM roles
UNION ALL
SELECT 'permissions', COUNT(*) FROM permissions
UNION ALL
SELECT 'stores', COUNT(*) FROM stores;
GO

SELECT TOP 10 user_id, full_name, email, phone, gender, birth_date, status, last_login_at
FROM users
ORDER BY user_id;
GO

SELECT TOP 10 store_id, store_code, store_name, contact_email, contact_phone, district, province, status
FROM stores
ORDER BY store_id;
GO
